from docx import Document
from lxml import etree

doc = Document("/root/offer_letter_template.docx")

# Search for DOC_ID and all placeholders in the full XML
body_xml = etree.tostring(doc.element.body, pretty_print=True).decode()

import re
placeholders = re.findall(r'\{\{[^}]+\}\}', body_xml)
print("All placeholders found:")
for p in sorted(set(placeholders)):
    print(f"  {p}")

# Also check for split placeholders by looking for {{ without }}
print("\nChecking for split runs...")
for i, p in enumerate(doc.paragraphs):
    for j, run in enumerate(p.runs):
        if '{{' in run.text and '}}' not in run.text:
            print(f"  SPLIT at paragraph {i}, run {j}: [{run.text}]")
            if j+1 < len(p.runs):
                print(f"    next run: [{p.runs[j+1].text}]")
